SELECT booking_id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE account_id = #{accountId}

SELECT booking_id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE account_id = #{accountId}
AND status IN ('BOOKED', 'CANCELED')
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT booking_id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE event_schedule_id = #{eventScheduleId}
ORDER BY booking_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_booking
WHERE account_id = #{accountId}

SELECT COUNT(*)
FROM tb_booking
WHERE event_schedule_id = #{eventScheduleId}

SELECT booking_id, event_schedule_id, seat_id, account_id, tenant_id, payment_id, status, created_at, updated_at
FROM tb_booking
WHERE booking_id = #{bookingId}

SELECT event_schedule_id AS eventScheduleId, COUNT(*) AS ticketCount FROM tb_booking WHERE status = 'BOOKED' AND event_schedule_id IN
#{id}
GROUP BY event_schedule_id

SELECT booking_id, event_schedule_id, tenant_id
FROM tb_booking
WHERE account_id = #{accountId}

    AND booking_id < #{cursor}

ORDER BY booking_id DESC
LIMIT #{size}

